package com.example.workout.workout.entity;
import com.example.workout.workout.model.WorkoutSegmentType; import jakarta.persistence.*; import lombok.*;
@Entity @Table(name="workout_segments") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder(setterPrefix="with")
public class WorkoutSegmentEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="workout_id",nullable=false) private WorkoutEntity workout; @Column(nullable=false) private Integer position; @Enumerated(EnumType.STRING) @Column(name="segment_type",nullable=false,length=30) private WorkoutSegmentType segmentType; @Column(length=200) private String name; private Integer repetitions; private Integer distanceMeters; private Integer durationSeconds; private Integer targetPaceSecondsPerKm; private Integer actualPaceSecondsPerKm; private Integer restDistanceMeters; private Integer restDurationSeconds; private Integer averageHeartRate; private Integer maxHeartRate; private Integer averageCadence; private Integer averagePowerWatts; private Integer elevationGainMeters; @Column(length=1000) private String description; }
